import {createProfileStore,filterEvents,csvFromRows} from '/profile-store.js';
/* Browser UI has no API keys and renders all provider/model content as escaped text. */
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const categories=['results','M&A','management_change','litigation','fund_raise','capex','credit_rating','pledging'];
const defaults={price:4,volume:2,hours:24,categories:[...categories],read:[],saved:[],notifications:false,whatsapp:{enabled:false,frequency:'instant',filings:true,prices:true}};
let settings={...defaults};try{settings={...defaults,...JSON.parse(localStorage.getItem('finn-settings')||'{}')}}catch{}
settings.whatsapp={...defaults.whatsapp,...(settings.whatsapp&&typeof settings.whatsapp==='object'?settings.whatsapp:{})};
const profileStore=createProfileStore({getItem:k=>localStorage.getItem(k),setItem:(k,v)=>localStorage.setItem(k,v)});
let profilePage='overview',activityFilter='all',activeReport='activity';
let view='portfolio',data=null,result=null,health=null,loading=false,researchLoading=false,seenLive=new Set(),lastMode='replay';
function updateThemeControls(){
 const dark=window.FinnTheme.current()==='dark',button=$('#theme-toggle'),label='Switch to '+(dark?'light':'dark')+' mode';
 button.setAttribute('aria-label',label);button.setAttribute('title',label);button.setAttribute('aria-pressed',String(dark));
 button.innerHTML=`<svg viewBox="0 0 24 24" aria-hidden="true">${dark?'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>':'<path d="M20 14a8 8 0 0 1-10-10 8 8 0 1 0 10 10Z"/>'}</svg><span>${dark?'Light':'Dark'}</span>`;
 document.querySelectorAll('[data-theme-state]').forEach(el=>el.textContent=dark?'Dark':'Light');
}
window.addEventListener('finn-theme-change',()=>{updateThemeControls();if(view==='profile')renderProfile()});
function persist(){try{localStorage.setItem('finn-settings',JSON.stringify(settings))}catch{toast('Browser storage is unavailable; settings last for this session.')}}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000)}
function date(value){return new Date(value).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Kolkata'})}
function time(value){return new Date(value).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Kolkata'})}
function relative(value){const hours=Math.max(0,Math.round((Date.parse(data.asOf)-Date.parse(value))/3600000));return hours<1?'Just filed':`${hours}h ago`}
function number(value){return value===null||value===undefined?'—':new Intl.NumberFormat('en-IN',{maximumFractionDigits:1}).format(value)}
function change(value){return value===null||value===undefined?'—':`${value>0?'+':''}${value.toFixed(1)}%`}
function errorBox(errors){return errors?.length?`<div class="error"><b>Coverage is incomplete.</b> Available data remains below.<details><summary>${errors.length} source notice${errors.length>1?'s':''}</summary>${errors.map(e=>`<div>${esc(e)}</div>`).join('')}</details></div>`:''}
let portfolioSort='name',portfolioMetric='price',chartTicker=null,chartDays=30;
function setView(next){view=next;document.body.classList.toggle('profile-mode',next==='profile');location.hash=next;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#breadcrumb').textContent={brief:'Stocks',research:'Research',portfolio:'Stocks',rules:'Your alerts',profile:'Profile'}[view];$('.product-nav [data-view="brief"]').classList.toggle('active',['brief','portfolio'].includes(view));render();window.scrollTo({top:0,behavior:'instant'})}
async function getDigest(){
  if(loading)return;loading=true;$('#refresh').disabled=true;$('#global-status').innerHTML='<p class="status-line">Refreshing the brief…</p>';
  const mode=$('#mode').value;
  try{
    const r=await fetch(`/api/digest?mode=${mode}&hours=${settings.hours}&price=${settings.price}&volume=${settings.volume}`);const body=await r.json();if(!r.ok)throw Error(body.error);
    if(mode==='live'&&lastMode==='live'&&settings.notifications&&'Notification'in window&&Notification.permission==='granted'){
      const ids=[...body.announcements.filter(i=>i.score>=75&&settings.categories.includes(i.category)).map(i=>({id:i.id,text:`${i.ticker}: ${i.title}`})),...body.holdings.flatMap(h=>h.signal.alerts.map(a=>({id:`${h.ticker}:${h.signal.date}:${a.type}`,text:`${h.ticker}: ${a.text}`})))];
      for(const i of ids)if(!seenLive.has(i.id))new Notification('FINN · New signal',{body:i.text});
      ids.forEach(i=>seenLive.add(i.id));
    }else if(mode==='live'){
      seenLive=new Set([...body.announcements.map(i=>i.id),...body.holdings.flatMap(h=>h.signal.alerts.map(a=>`${h.ticker}:${h.signal.date}:${a.type}`))]);
    }
    data=body;for(const item of body.announcements)if(settings.saved.includes(item.id)&&!profileStore.get().filings[item.id])profileStore.rememberFiling(item);lastMode=mode;$('#global-status').innerHTML='';render();
  }catch(e){$('#global-status').innerHTML=`<div class="error">${esc(e.message)} ${data?'Previous data remains visible.':'Try refreshing.'}</div>`;if(!data)$('#view').innerHTML='<div class="empty">FINN could not load the brief. Use refresh to retry.</div>';}
  finally{loading=false;$('#refresh').disabled=false;}
}
function render(){
  renderMarket();updateProfileAvatar();
  if(view==='profile'){renderProfile();return}
  if(view==='research'){renderResearch();return}if(view==='rules'){renderRules();return}
  if(!data){$('#view').innerHTML='<div class="loading">Finding the signal…</div>';return}
  if(view==='portfolio'){renderPortfolio();return}renderBrief();
}
function heading(eyebrow,title,description,extra=''){return `<div class="heading-row"><div class="eyebrow">${eyebrow}</div>${extra}</div><h1>${title}</h1><p class="intro">${description}</p>`}
function companyLogo(ticker){
 const symbols=['INFY','TCS','HDFCBANK','ICICIBANK','RELIANCE','LT','ITC','HINDUNILVR','SUNPHARMA','DRREDDY','MARUTI','TITAN','TATAPOWER','ULTRACEMCO','PERSISTENT','DIXON','APLAPOLLO','KEI'];
 return symbols.includes(ticker)?`<span class="company-logo"><img src="/logos/${encodeURIComponent(ticker)}.webp" alt="" width="28" height="28" decoding="async"></span>`:'';
}
function filingCard(item){const saved=settings.saved.includes(item.id),read=settings.read.includes(item.id);return `<article class="filing-card focus ${read?'read':''}"><div class="card-top">${companyLogo(item.ticker)}<span class="ticker">${esc(item.ticker)}</span><span class="pill ${item.category==='management_change'?'orange':''}">${esc(item.category.replaceAll('_',' '))}</span><span class="card-time">${relative(item.publishedAt)}</span></div><h3>${esc(item.title)}</h3><p>${esc(item.summary)}</p><div class="why"><span>↗</span><span>${esc(item.reason)}</span></div><div class="card-actions"><button class="text-button" data-open-filing="${esc(item.id)}">${item.sample?'Explore scenario':'Open filing'} ↗</button><button class="text-button subtle" data-read="${esc(item.id)}">${read?'Read ✓':'Mark read'}</button><button class="text-button subtle" data-save="${esc(item.id)}" aria-pressed="${saved}">${saved?'Saved ✓':'Save +'} </button></div></article>`}
function priceCard(h){return `<article class="filing-card"><div class="card-top">${companyLogo(h.ticker)}<span class="ticker">${esc(h.ticker)}</span><span class="pill orange">PRICE & VOLUME</span><span class="card-time">${esc(h.signal.date)}</span></div><h3>${h.signal.multiple>=settings.volume?`${number(h.signal.multiple)}× the usual volume`:`A ${change(h.signal.change)} move worth a look`}</h3><p>${h.signal.alerts.map(a=>esc(a.text)).join(' ')}</p><div class="why">${data.mode==='replay'?'Illustrative EOD data.':'End-of-day bars · Yahoo Finance.'} ${h.signal.baselineDays} prior sessions in the baseline. A move alone does not explain its cause.</div><div class="card-actions"><button class="text-button" data-research="${esc(h.ticker)}">Research the business →</button>${h.source?`<a class="source-link" href="${esc(h.source)}" target="_blank" rel="noopener noreferrer">Price source ↗</a>`:'<span class="fine-print">Scenario data</span>'}</div></article>`}
function renderBrief(){
  const material=data.announcements.filter(i=>i.score>=75&&settings.categories.includes(i.category)),routine=data.announcements.filter(i=>!material.includes(i)),signals=data.holdings.filter(h=>h.signal.alerts.length);
  const unread=material.filter(i=>!settings.read.includes(i.id)).length;$('#nav-count').textContent=unread+signals.length;
  $('#view').innerHTML=heading('PORTFOLIO INTELLIGENCE','Your daily brief',`Your ${data.holdings.length} companies. The changes that deserve your attention.`,`<span class="date-label">${esc(date(data.asOf)).toUpperCase()}</span>`)+
  (data.mode==='replay'?'<div class="replay-note"><b>◈ SCENARIO REPLAY</b><span>Announcements, prices and result numbers are illustrative. Research uses real, dated company documents.</span></div>':`<div class="status-line"><span class="status-dot"></span>Live providers · refreshed ${esc(time(data.asOf))} IST · ${data.coverage.prices}/${data.coverage.total} price histories. ${esc(data.coverage.filings)}.</div>`)+
  errorBox(data.errors)+`<div class="summary-grid"><div class="summary-cell"><span class="arrow">↗</span><strong>${unread}</strong><span>material filings to read</span></div><div class="summary-cell"><strong>${signals.length}</strong><span>price / volume signals</span></div><div class="summary-cell"><strong>${routine.length}</strong><span>lower-priority filings tucked away</span></div></div>
  <div class="brief-grid"><section><div class="section-head"><h2>Worth your attention</h2><div class="windows" aria-label="Digest window">${[24,72,168].map(h=>`<button data-hours="${h}" class="${settings.hours===h?'selected':''}" aria-pressed="${settings.hours===h}">${h===24?'24h':h===72?'3d':'7d'}</button>`).join('')}</div></div><div class="custom-hours"><label for="hours">Look back <input id="hours" type="number" min="1" max="168" value="${settings.hours}"> hours</label></div>
  ${material.map(filingCard).join('')}${signals.map(priceCard).join('')}${!material.length&&!signals.length?'<div class="empty">A quiet window. No disclosures or moves cross your current rules.</div>':''}
  <details class="routine"><summary>${routine.length} lower-priority filings · nothing discarded</summary><ul>${routine.map(i=>`<li><b>${esc(i.ticker)}</b> · ${esc(i.title)}<span>${esc(i.category)} · ${esc(date(i.publishedAt))} ${esc(time(i.publishedAt))} IST</span><button class="text-button" data-open-filing="${esc(i.id)}">${i.sample?'Scenario details':'View filing'} →</button></li>`).join('')||'<li>No other filings in this window.</li>'}</ul></details><p class="fine-print">Classification is a transparent title-based triage rule, not a finding that a filing is immaterial. Read the original before acting.</p><button class="text-button" id="export-brief">Download this brief ↓</button></section>
  <aside class="rail"><section class="rail-panel dark"><span class="eyebrow">GO ONE LEVEL DEEPER</span><h2>A good question<br>beats another feed.</h2><p>What did management promise? What did the business deliver? Start with the evidence.</p><button class="primary" id="case-study">Explore the Infosys guidance check ↗</button></section><section class="rail-panel"><div class="section-head"><h2>On the radar</h2><span class="eyebrow">EOD</span></div>${data.holdings.slice().sort((a,b)=>Math.abs(b.signal.change||0)-Math.abs(a.signal.change||0)).slice(0,4).map(h=>`<div class="mini-stock">${companyLogo(h.ticker)}<div><strong>${esc(h.ticker)}</strong><small>${esc(h.sector)}</small></div><div class="move ${h.signal.change<0?'negative':'positive'}">${change(h.signal.change)}<small>${h.signal.multiple?number(h.signal.multiple)+'× vol':'Unavailable'}</small></div></div>`).join('')}<p class="fine-print">${data.mode==='replay'?'Illustrative bars, not current prices.':'Last completed EOD bar; date is shown in Portfolio.'}</p></section><section class="rail-panel"><span class="eyebrow">YOUR ATTENTION BUDGET</span><h2>You set the signal.</h2><p>Watching ±${settings.price}% moves and ${settings.volume}× volume. ${settings.categories.length} material categories enabled.</p><button data-view="rules" class="text-button">Adjust your rules →</button></section></aside></div>`;
}
function renderResearch(){
  $('#view').innerHTML=heading('COMPANY RESEARCH','Research, backed by evidence','Ask a specific question. Follow it back to the company’s own words.')+
  `<form id="research-form" class="research-form"><input id="ticker" aria-label="NSE ticker" maxlength="24" value="${esc(result?.ticker||'INFY')}" placeholder="NSE symbol" required><input id="question" aria-label="Research question" maxlength="600" placeholder="Where do cash flow and management’s story diverge?" value="${esc(result?.question||'')}" required><button class="primary" ${researchLoading?'disabled':''}>${researchLoading?'Reading…':'Find the evidence ↗'}</button></form><div class="quick-questions">${['Business segments and revenue mix','Cash flow and cash conversion','Revenue growth and margin guidance','Debt, leverage and capital expenditure'].map(q=>`<button class="chip" data-question="${esc(q)}">${esc(q)}</button>`).join('')}</div>
  <div class="status-line"><span class="status-dot"></span>${health?.modelConfigured?'AI synthesis configured; citation and quote checks enabled.':'Evidence mode · no paid key required. Optional AI synthesis is available on the server.'}</div>
  ${researchLoading?'<div class="loading">Reading the primary evidence…</div><p class="fine-print">New tickers require document discovery and PDF extraction. This can take a minute.</p>':result?researchResult():`<div class="company-choices">${[['INFY','Infosys'],['TCS','Tata Consultancy'],['HDFCBANK','HDFC Bank'],['RELIANCE','Reliance Industries']].map(([t,n])=>`<button class="company-choice" data-research="${t}"><b>${t} ↗</b><span>${n} · source snapshot</span></button>`).join('')}</div><div class="research-answer"><span class="eyebrow">THE FEATURED QUESTION · HISTORICAL FY25</span><h2>Did Infosys meet its final growth guidance?</h2><p class="intro">A narrow test of narrative against numbers, with both sides of the comparison sourced.</p><button class="primary" id="case-study">Open the guidance check →</button></div><p class="fine-print">Four companies have bundled annual-report and transcript snapshots. Any valid NSE symbol can use live Screener link discovery and exchange-hosted PDFs. Availability and text extraction vary by company.</p>`}`;
}
function researchResult(){return errorBox(result.errors)+`<div class="research-layout"><article class="research-answer"><span class="eyebrow">${esc(result.ticker)} · ${result.mode==='ai'?'AI INTERPRETATION':'PRIMARY-SOURCE NOTES'}</span><h2>${esc(result.question)}</h2><p class="fine-print">${esc(result.origin)} · retrieved ${result.asOf?esc(date(result.asOf)):'—'}. Document dates may be older. ${result.mode==='evidence'?'Bundled results are curated factual notes with short verified quotations. Live results use extracted passages.':''}</p>
  ${result.caseStudy?`<div class="summary-grid"><div class="summary-cell"><strong>4.5–5%</strong><span>final FY25 growth guidance</span></div><div class="summary-cell"><strong>4.2%</strong><span>FY25 growth delivered</span></div><div class="summary-cell"><strong>−0.3pp</strong><span>below the lower bound</span></div></div>`:''}
  ${result.claims.map(c=>`<div class="answer-item"><p>${esc(c.text)}</p><button class="citation" data-citation="${esc(c.citation)}">${esc(c.citation)} · inspect evidence ↗</button></div>`).join('')||'<div class="empty">No supported answer. FINN will not fill a source gap with a guess.</div>'}
  <p class="fine-print">${result.limits.map(esc).join('<br>')}</p><button class="text-button" id="refresh-research">Fetch newest available sources ↻</button></article><aside class="research-sources"><h3 class="sources-heading">Source notebook · ${result.documents.length} documents</h3>${result.documents.map(d=>`<div class="source-card"><strong>${esc(d.title)}</strong><span>${esc(d.kind.replaceAll('_',' '))} · ${d.pages} PDF pages · ${d.chunks} indexed passage${d.chunks===1?'':'s'}</span><a href="${esc(d.url)}" target="_blank" rel="noopener noreferrer">Open primary document ↗</a><span>SHA-256 ${esc(d.sha256.slice(0,14))}…</span></div>`).join('')}<p class="fine-print">Screener is a document directory only. Its tables, summaries and third-party commentary are excluded. PDF page references count from the cover, and may differ from printed page numbers.</p></aside></div>`}
async function ask(ticker,question,fresh=false){
  if(researchLoading)return;researchLoading=true;result={ticker,question,claims:[],evidence:[],documents:[],limits:[],errors:[]};setView('research');
  try{const r=await fetch('/api/research',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ticker,question,fresh})});const body=await r.json();if(!r.ok)throw Error(body.error);result=body;}catch(e){result.errors=[e.message];result.origin='Source unavailable';result.mode='evidence';}
  finally{researchLoading=false;profileStore.record('research',{title:'Researched '+String(result.ticker).toUpperCase(),ticker:result.ticker,question:result.question,detail:result.question,status:result.evidence?.length?'Source evidence found':'No evidence available',mode:'primary_sources'});if(view==='research')renderResearch();else if(view==='profile')renderProfile();}
}
async function caseStudy(){
  try{const r=await fetch('/api/case-study');const body=await r.json();if(!r.ok)throw Error(body.error);result=body;profileStore.record('research',{title:'Opened the Infosys guidance check',ticker:'INFY',question:body.question,detail:body.question,status:'Historical primary-source comparison',mode:'primary_sources'});setView('research')}catch(e){toast(e.message)}
}

function weightedMove(){return data&&data.holdings.every(h=>Number.isFinite(h.signal.change))?data.holdings.reduce((n,h)=>n+h.signal.change*h.weight/100,0):null;}
function renderMarket(){
 if(!data){$('#market-strip').innerHTML='';return}
 const move=weightedMove(),signals=data.holdings.filter(h=>h.signal.alerts.length).length;
 $('#market-strip').innerHTML=`<div class="market-card"><strong>PORTFOLIO · 1D</strong><span class="market-value">${data.holdings.length} companies</span><span class="${move<0?'negative':'positive'}">${change(move)}</span><br><small>Weighted move · mock allocations</small></div><div class="market-card"><strong>ON YOUR RADAR</strong><span class="market-value">${signals} signals</span><small>Price & volume</small><br><small>${data.mode==='replay'?'Illustrative EOD snapshot':esc(date(data.asOf))+' · last completed EOD'}</small></div>`;
 $('#nav-count').textContent=data.announcements.filter(i=>i.score>=75&&settings.categories.includes(i.category)&&!settings.read.includes(i.id)).length+signals;
}
function chartSvg(history,large=false,negative=false){
 const series=(history||[]).filter(p=>Number.isFinite(p.close));if(series.length<2)return '<span class="holding-chart-placeholder">No history</span>';
 const w=large?640:96,h=large?250:34,pad=large?16:3,low=Math.min(...series.map(p=>p.close)),high=Math.max(...series.map(p=>p.close)),spread=high-low||Math.max(high*.01,1),color=negative?'#eb5b3c':'#00b386';
 const points=series.map((p,i)=>`${(pad+i*(w-pad*2)/(series.length-1)).toFixed(2)},${(h-pad-(p.close-low)/spread*(h-pad*2)).toFixed(2)}`);
 const grid=large?Array.from({length:5},(_,i)=>`<line x1="0" y1="${20+i*53}" x2="${w}" y2="${20+i*53}" stroke="#242c29" stroke-dasharray="3 4"/>`).join(''):'';
 const area=large?`<polygon points="${pad},${h} ${points.join(' ')} ${w-pad},${h}" fill="${color}" fill-opacity="0.07"/>`:'';
 return `<svg class="${large?'large-chart':'sparkline'}" viewBox="0 0 ${w} ${h}" role="img" aria-label="${series.length} end-of-day closing prices">${grid}${area}<polyline points="${points.join(' ')}" stroke="${color}" stroke-width="${large?2:1.5}" stroke-linejoin="round" stroke-linecap="round" fill="none"/></svg>`;
}
function renderPortfolio(){
 const move=weightedMove(),priceAlerts=data.holdings.filter(h=>h.signal.alerts.some(a=>a.type==='price')).length;
 const rows=[...data.holdings].sort(portfolioSort==='name'?(a,b)=>a.name.localeCompare(b.name):(a,b)=>Math.abs(b.signal.change||0)-Math.abs(a.signal.change||0));
 $('#view').innerHTML=`<div class="portfolio-layout"><section><h1 class="holdings-title">Holdings <span>(${data.holdings.length})</span></h1><div class="portfolio-summary"><div><small>Companies tracked</small><strong>${data.holdings.length}</strong><span class="summary-detail">Across ${new Set(data.holdings.map(h=>h.sector)).size} sectors</span></div><div><small>Weighted 1D move</small><strong class="${move<0?'negative':'positive'}">${change(move)}</strong><span class="summary-detail">Using mock allocations</span></div><div><small>Portfolio allocation</small><strong>${data.holdings.reduce((n,h)=>n+h.weight,0)}%</strong><span class="summary-detail">Illustrative weights</span></div><div><small>Price alerts</small><strong class="${priceAlerts?'negative':''}">${priceAlerts} triggered</strong><span class="summary-detail">Your ±${settings.price}% rule</span></div></div>
 <div class="status-line">${data.mode==='replay'?'Scenario replay · illustrative prices and allocations':'Yahoo Finance · last completed EOD bars'}</div>${errorBox(data.errors)}<div class="holding-tools"><button id="sort-holdings" aria-label="Change holdings sort order">Sort ⇅ · ${portfolioSort==='name'?'Name':'Largest move'}</button><button id="holding-metric" aria-label="Toggle price and rupee change">‹ › ${portfolioMetric==='price'?'Price / 1D (%)':'1D change ₹ / (%)'}</button></div><div class="holdings-list">${rows.map(h=>{
 const rupeeChange=Number.isFinite(h.signal.change)&&Number.isFinite(h.signal.close)?h.signal.close-h.signal.close/(1+h.signal.change/100):null;
 const value=portfolioMetric==='price'?h.signal.close:rupeeChange;
 return `<button class="holding-row" data-chart="${esc(h.ticker)}" aria-label="Open ${esc(h.name)} price chart"><span class="holding-identity"><span class="holding-logo"><img src="/logos/${encodeURIComponent(h.ticker)}.webp" alt="" width="36" height="36" decoding="async"></span><span class="holding-name"><strong>${esc(h.name)}</strong><small>${h.weight}% allocation</small></span></span>${chartSvg(h.history,false,h.signal.change<0)}<span class="holding-values"><strong class="${portfolioMetric!=='price'?(value<0?'negative':'positive'):''}">${value===null||value===undefined?'—':'₹'+number(value)}</strong><small class="${h.signal.change<0?'negative':'positive'}">(${change(h.signal.change)})</small></span></button>`;
 }).join('')}</div><p class="fine-print holdings-asof">Tap a holding to inspect its EOD chart. Lines use the available closing-price history, not intraday trading data. ${data.mode==='replay'?'Replay observations are synthetic.':''} Allocations are mock weights; the weighted daily move is not a brokerage account return.</p></section>
 <aside class="portfolio-side"><section class="rail-panel"><h2>Portfolio signals</h2><p>The changes crossing your rules, together in one place.</p>${data.holdings.filter(h=>h.signal.alerts.length).map(h=>`<div class="mini-stock">${companyLogo(h.ticker)}<div><strong>${esc(h.ticker)}</strong><small>${number(h.signal.multiple)}× volume</small></div><span class="move ${h.signal.change<0?'negative':'positive'}">${change(h.signal.change)}</span></div>`).join('')||'<p>No thresholds crossed.</p>'}<button data-view="brief" class="text-button">View your daily brief →</button></section><section class="rail-panel dark"><h2>Know what you own.</h2><p>Go beyond the price. Explore company reports, cash flow and management guidance.</p><button data-view="research" class="primary">Research a company →</button></section></aside></div>`;
}
function showChart(ticker,days=30){
 const h=data?.holdings.find(h=>h.ticker===ticker);if(!h)return;if(chartTicker!==ticker||!$('#evidence-dialog').open)profileStore.record('chart_view',{title:'Viewed '+ticker+' price chart',ticker,detail:'End-of-day closing-price history',mode:data.mode});chartTicker=ticker;chartDays=days;
 const series=(h.history||[]).slice(-days),last=series.at(-1),first=series[0];
 dialog(`<div class="chart-heading"><h2>${esc(h.ticker)} <span class="fine-print">· NSE</span></h2><span class="pill">EOD chart</span></div><p class="fine-print">${esc(h.name)}</p><div class="chart-price">${h.signal.close?'₹'+number(h.signal.close):'Price unavailable'}</div><div class="chart-change ${h.signal.change<0?'negative':'positive'}">${change(h.signal.change)} <span class="fine-print">1D close-to-close</span></div><div class="chart-toolbar"><span>Closing price · daily</span><div>${[5,30].map(n=>`<button data-chart-window="${n}" class="${n===days?'selected':''}" aria-pressed="${n===days}">${n===5?'5D':'All'}</button>`).join('')}</div></div>${chartSvg(series,true,h.signal.change<0)}<div class="chart-date-axis"><span>${first?esc(date(first.date)):''}</span><span>${last?esc(date(last.date)):''}</span></div><div class="chart-foot"><p>${data.mode==='replay'?'Illustrative scenario data.':'Yahoo Finance daily observations.'} ${series.length} available sessions. No intraday or trading execution.</p><button data-research="${esc(ticker)}" class="primary">Research ${esc(ticker)} →</button></div>`,true);
}
function renderRules(){
  $('#view').innerHTML=heading('YOUR PREFERENCES','Alerts & notifications','Set the changes worth interrupting your day. FINN keeps the rest within reach.')+`<form id="rules-form"><div class="rule-grid"><section class="rule-card"><span class="eyebrow">EOD THRESHOLDS</span><h2>A move worth a second look.</h2><label class="rule-label">Daily price move ± <input name="price" type="number" min="0.1" max="30" step="0.1" value="${settings.price}" required> %</label><label class="rule-label">Volume versus prior 20 sessions <input name="volume" type="number" min="1" max="10" step="0.1" value="${settings.volume}" required> ×</label><p class="settings-note">These rules watch completed EOD bars. They do not provide intraday price alerts.</p><label class="check"><input name="notifications" type="checkbox" ${settings.notifications?'checked':''}> Browser notifications while FINN is open</label><p class="fine-print">Live mode checks every 60 seconds while this tab is visible. No background service, scheduled ingestion, email or mobile push delivery is claimed.</p></section><section class="rule-card"><span class="eyebrow">MATERIAL DISCLOSURES</span><h2>The subjects you care about.</h2>${categories.map(c=>`<label class="check"><input name="category" type="checkbox" value="${c}" ${settings.categories.includes(c)?'checked':''}> ${esc(c.replaceAll('_',' '))}</label>`).join('')}<p class="fine-print">Disabling a category moves it into the collapsed filing list. It does not delete it.</p></section></div><button class="primary save-rule">Save my rules →</button><p class="fine-print">Rules, read states and saved items are stored in this browser. ${settings.saved.length} saved item${settings.saved.length===1?'':'s'}.</p></form><button class="text-button" id="view-saved">View saved filings →</button>`;
}
function dialog(content,dark=false){$('#evidence-dialog').classList.remove('report-dialog');$('#evidence-dialog').classList.toggle('chart-dialog',dark);$('#dialog-content').innerHTML=content;if(!$('#evidence-dialog').open)$('#evidence-dialog').showModal()}
function showFiling(id){const item=data?.announcements.find(i=>i.id===id)||profileStore.get().filings[id];if(!item)return;profileStore.record('filing_view',{title:'Opened '+item.ticker+' filing',ticker:item.ticker,detail:item.title,target:item.id,mode:item.sample?'replay':'live'});if(view==='profile')renderProfile();
  if(item.sample){dialog(`<h2>${esc(item.title)}</h2><p class="error">Illustrative scenario. This is not a claim that this event happened at ${esc(item.ticker)}.</p><p class="fine-print">The replay tests prioritization, reading and saving. Company research is separately grounded in real documents.</p>${item.category==='results'&&data?.sampleResults?.length?`<div class="table-wrap"><table class="result-table"><caption>Illustrative consolidated figures · ₹ crore</caption><thead><tr><th>Metric</th><th>Quarter</th><th>QoQ</th><th>YoY</th></tr></thead><tbody>${data.sampleResults.map(row=>`<tr><td>${row.metric.toUpperCase()}</td><td>${number(row.current)}</td><td>${change(row.qoq)}</td><td>${change(row.yoy)}</td></tr>`).join('')}</tbody></table></div><p class="fine-print">Revenue rises while profit compresses versus the prior quarter. An illustration of why both dimensions belong together. No live filing extraction is implied.</p>`:''}<button class="primary" data-research="${esc(item.ticker)}">Research ${esc(item.ticker)} using real sources →</button>`)}
  else if(item.url){dialog(`<h2>${esc(item.title)}</h2><p>${esc(item.reason)}</p><a class="source-link" href="${esc(item.url)}" target="_blank" rel="noopener noreferrer">Read the exchange filing ↗</a><p class="fine-print">${esc(date(item.publishedAt))} ${esc(time(item.publishedAt))} IST. Classification is provisional and based on the filing title.</p>`)}
  else dialog('<h2>Filing link unavailable</h2><p>The exchange returned this record without an allowlisted attachment URL.</p>');
}

const profileMenus=[['activity','Your activity','Research, filings and preference changes'],['saved','Saved filings','Pick up where you left off'],['history','Research history','Your company questions and source checks'],['reports','Reports & statements','View and download your workspace data'],['preferences','Alert preferences','Price, volume and disclosure rules'],['notifications','Notifications','Browser alerts and WhatsApp demo'],['help','Help & about','How your FINN workspace works']];
function profileIcon(kind){
 const paths={whatsapp:'M21 11.5a9 9 0 0 1-13 8L3 21l1.5-5A9 9 0 1 1 21 11.5ZM8 7c0 5 4 9 9 9l1-3-3-1-1 2c-2-1-3-2-4-4l2-1-1-3Z',notifications:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',activity:'M3 12h4l3-7 4 14 3-7h4',saved:'M6 3h12v18l-6-4-6 4Z',history:'M21 12a9 9 0 1 1-3-6M21 3v6h-6M12 7v5l3 2',reports:'M6 3h9l4 4v14H6ZM14 3v5h5M9 12h7M9 16h7',preferences:'M3 7h18M3 17h18M8 3v8m8 2v8',help:'M9 9a3 3 0 1 1 4 3v3M13 18h.01',research:'M16 16l5 5M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5'};
 return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[kind]||paths.activity}"/></svg>`;
}
function profileInitials(){const name=profileStore.get().name.trim();return name?name.split(/\s+/).slice(0,2).map(p=>p[0]).join('').toUpperCase():'Y';}
function updateProfileAvatar(){const avatar=$('.top-avatar');if(avatar)avatar.textContent=profileInitials();}
function savedFilings(){const state=profileStore.get();return settings.saved.map(id=>state.filings[id]||data?.announcements.find(f=>f.id===id)||{id,title:'Saved filing details are not available in this browser yet.',ticker:'Filing',category:'unavailable'});}
function eventLabel(event){return event.mode==='replay'?'Scenario replay':event.mode==='primary_sources'?'Primary sources':'';}
function eventIcon(type){return type==='research'?'research':type.includes('download')?'download':['save','unsave'].includes(type)?'saved':['rules_updated','notification_preferences_updated'].includes(type)?'preferences':'activity';}
function activityRows(events){
 return events.map(event=>`<article class="activity-row"><span class="activity-icon">${profileIcon(eventIcon(event.type))}</span><div><strong>${esc(event.title||event.type.replaceAll('_',' '))}</strong>${event.detail?`<p>${esc(event.detail)}</p>`:''}<small>${esc(date(event.at))} · ${esc(time(event.at))} IST${eventLabel(event)?' · '+esc(eventLabel(event)):''}${event.status?' · '+esc(event.status):''}</small>${event.type==='research'&&event.ticker?`<button class="text-button" data-resume-research="${esc(event.id)}">Open research →</button>`:''}</div></article>`).join('');
}
function profileEmpty(title,detail){return `<div class="profile-empty"><span class="activity-icon">${profileIcon('activity')}</span><h3>${title}</h3><p>${detail}</p><button class="text-button" data-view="brief">Explore your daily brief →</button></div>`;}
